// music buddies: the cute animated character on the Moods tab + the full player's play / pause button
// svgs are generated by scripts/gen_characters.py (edit that, then re-run it)
import cat from '../shared/svg/cat.svg?raw'
import panda from '../shared/svg/panda.svg?raw'
import tiger from '../shared/svg/tiger.svg?raw'
import polar from '../shared/svg/polar.svg?raw'
import bunny from '../shared/svg/bunny.svg?raw'
import penguin from '../shared/svg/penguin.svg?raw'

const SVGS = { cat, panda, tiger, polar, bunny, penguin }

export type Character = keyof typeof SVGS

export const CHARACTERS = Object.keys(SVGS) as Character[]

export const CHARACTER_LABELS: Record<Character, string> = {
  cat: 'Kitty',
  panda: 'Panda',
  tiger: 'Tiger',
  polar: 'Polar bear',
  bunny: 'Bunny',
  penguin: 'Penguin',
}

export const isCharacter = (value: unknown): value is Character =>
  CHARACTERS.includes(value as Character)

// the same svg can be on screen several times (menu, player, settings): give each place
// its own gradient id, or one hidden copy can blank out the others' fur
export const characterSvg = (character: Character, scope: string) =>
  SVGS[character].replaceAll('pg-fur-', `pg-fur-${scope}-`)
